const express = require('express');
const k8s = require('@kubernetes/client-node');
const { verifyDevToken } = require('../auth');

const app = express();
app.use(express.json());

const kc = new k8s.KubeConfig();
kc.loadFromDefault();
const k8sApi = kc.makeApiClient(k8s.CoreV1Api);

app.post('/api/ai/tools/get-pod-logs', verifyDevToken, async (req, res) => {
  const { namespace, podName, containerName } = req.body.parameters || {};

  // Validate that the developer has RBAC access to the requested namespace
  const allowedNamespaces = req.user.permittedNamespaces || [];
  if (!allowedNamespaces.includes(namespace) && !req.user.isClusterAdmin) {
    return res.status(403).json({
      error: `Access denied: you do not have permission to inspect pods in namespace '${namespace}'`
    });
  }

  try {
    const logsResponse = await k8sApi.readNamespacedPodLog(
      podName,
      namespace,
      containerName
    );

    res.json({ pod: podName, namespace, logs: logsResponse.body });
  } catch (err) {
    res.status(500).json({ error: 'Failed to retrieve pod logs' });
  }
});

app.listen(8114);
